'use strict';

// MODULES //

var tape = require( 'tape' );
var Float32Array = require( '@stdlib/array/float32' );
var EPS = require( '@stdlib/constants/float32/eps' );
var sindexOfAlmostSameValue = require( './../lib/ndarray.js' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof sindexOfAlmostSameValue, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 6', function test( t ) {
	t.strictEqual( sindexOfAlmostSameValue.length, 6, 'has expected arity' );
	t.end();
});

tape( 'the function returns the first index of an element which is almost the same value as a provided search element', function test( t ) {
	var actual;
	var x;

	x = new Float32Array( [ 1.0, 1.0, 2.0, 2.0, 3.0, 3.0 ] );

	actual = sindexOfAlmostSameValue( x.length, 1.0, 1, x, 1, 0 );
	t.strictEqual( actual, 0, 'returns expected value' );

	t.end();
});

tape( 'the function returns `-1` if the function is unable to find a search element', function test( t ) {
	var actual;
	var x;

	x = new Float32Array( [ 1.0, 1.0, 2.0, 2.0, 3.0, 3.0 ] );

	actual = sindexOfAlmostSameValue( x.length, 4.0, 1, x, 1, 0 );
	t.strictEqual( actual, -1, 'returns expected value' );

	t.end();
});

tape( 'the function supports specifying a maximum allowed ULP difference', function test( t ) {
	var actual;
	var x;

	x = new Float32Array( [ 1.0+( 4.0*EPS ), 1.0+( 2.0*EPS ), 1.0+EPS ] );

	actual = sindexOfAlmostSameValue( x.length, 1.0, 0, x, 1, 0 );
	t.strictEqual( actual, -1, 'returns expected value' );

	actual = sindexOfAlmostSameValue( x.length, 1.0, 1, x, 1, 0 );
	t.strictEqual( actual, 2, 'returns expected value' );

	actual = sindexOfAlmostSameValue( x.length, 1.0, 2, x, 1, 0 );
	t.strictEqual( actual, 1, 'returns expected value' );

	actual = sindexOfAlmostSameValue( x.length, 1.0, 4, x, 1, 0 );
	t.strictEqual( actual, 0, 'returns expected value' );

	t.end();
});

tape( 'the function returns `-1` if provided an `N` parameter which is less than or equal to zero', function test( t ) {
	var actual;

	actual = sindexOfAlmostSameValue( 0, 2.0, 1, new Float32Array( [ 1.0, 2.0, 3.0 ] ), 1, 0 );
	t.strictEqual( actual, -1, 'returns expected value' );

	actual = sindexOfAlmostSameValue( -1, 2.0, 1, new Float32Array( [ 1.0, 2.0, 3.0 ] ), 1, 0 );
	t.strictEqual( actual, -1, 'returns expected value' );

	t.end();
});

tape( 'the function returns the first index when searching for `NaN`', function test( t ) {
	var actual;

	actual = sindexOfAlmostSameValue( 1, NaN, 1, new Float32Array( [ NaN ] ), 1, 0 );
	t.strictEqual( actual, 0, 'returns expected value' );

	t.end();
});

tape( 'the function distinguishes between -0 and +0', function test( t ) {
	var actual;

	actual = sindexOfAlmostSameValue( 1, 0.0, 0, new Float32Array( [ -0.0 ] ), 1, 0 );
	t.strictEqual( actual, -1, 'returns expected value' );

	actual = sindexOfAlmostSameValue( 1, -0.0, 0, new Float32Array( [ 0.0 ] ), 1, 0 );
	t.strictEqual( actual, -1, 'returns expected value' );

	actual = sindexOfAlmostSameValue( 1, 0.0, 0, new Float32Array( [ 0.0 ] ), 1, 0 );
	t.strictEqual( actual, 0, 'returns expected value' );

	actual = sindexOfAlmostSameValue( 1, -0.0, 0, new Float32Array( [ -0.0 ] ), 1, 0 );
	t.strictEqual( actual, 0, 'returns expected value' );

	t.end();
});

tape( 'the function supports an `x` stride', function test( t ) {
	var actual;
	var x;

	x = new Float32Array([
		1.0, // 0
		2.0,
		3.0, // 1
		4.0,
		5.0  // 2
	]);

	actual = sindexOfAlmostSameValue( 3, 3.0, 1, x, 2, 0 );
	t.strictEqual( actual, 1, 'returns expected value' );

	t.end();
});

tape( 'the function supports a negative `x` stride', function test( t ) {
	var actual;
	var x;

	x = new Float32Array([
		1.0, // 2
		2.0,
		3.0, // 1
		4.0,
		5.0  // 0
	]);

	actual = sindexOfAlmostSameValue( 3, 3.0, 1, x, -2, 4 );
	t.strictEqual( actual, 1, 'returns expected value' );

	t.end();
});

tape( 'the function supports an `x` offset', function test( t ) {
	var actual;
	var x;

	x = new Float32Array([
		1.0,
		2.0, // 0
		3.0, // 1
		4.0, // 2
		5.0
	]);

	actual = sindexOfAlmostSameValue( 3, 4.0, 1, x, 1, 1 );
	t.strictEqual( actual, 2, 'returns expected value' );

	t.end();
});

tape( 'the function supports complex access patterns', function test( t ) {
	var actual;
	var x;

	x = new Float32Array([
		1.0,
		2.0, // 0
		3.0,
		4.0, // 1
		5.0,
		6.0  // 2
	]);

	actual = sindexOfAlmostSameValue( 3, 4.0, 1, x, 2, 1 );
	t.strictEqual( actual, 1, 'returns expected value' );

	t.end();
});
